Here is the commit message:
drm/xe: Fix memory leak in xe_vm_madvise_ioctl

When check_bo_args_are_sane() validation fails, jump to the new
free_vmas cleanup label to properly free the allocated resources.
This ensures proper cleanup in this error path.

Fixes: 293032eec4ba ("drm/xe/bo: Update atomic_access attribute on madvise")
Cc: stable@vger.kernel.org # v6.18+
Reviewed-by: Shuicheng Lin <shuicheng.lin@intel.com>
Signed-off-by: Varun Gupta <varun.gupta@intel.com>
Reviewed-by: Matthew Brost <matthew.brost@intel.com>
Link: https://patch.msgid.link/20260223175145.1532801-1-varun.gupta@intel.com
Signed-off-by: Tejas Upadhyay <tejas.upadhyay@intel.com>
(cherry picked from commit 29bd06faf727a4b76663e4be0f7d770e2d2a7965)
Signed-off-by: Rodrigo Vivi <rodrigo.vivi@intel.com>

Here is the root cause:
In the xe_vm_madvise_ioctl function, when `check_bo_args_are_sane()` fails, the code jumps to the `madv_fini` label, which does not free the allocated `madvise_range.vmas` array, resulting in a memory leak. The fix introduces a `free_vmas` label that performs the `kfree` before falling through to `madv_fini`.

Here is the patch:
  */
 int xe_vm_madvise_ioctl(struct drm_device *dev, void *data, struct drm_file *file)
 {
 	struct xe_device *xe = to_xe_device(dev);
 	struct xe_file *xef = to_xe_file(file);
 	struct drm_xe_madvise *args = data;
 	struct xe_vmas_in_madvise_range madvise_range = {.addr = args->start,
 							 .range =  args->range, };
 	struct xe_madvise_details details;
 	struct xe_vm *vm;
 	struct drm_exec exec;
 	int err, attr_type;

 	vm = xe_vm_lookup(xef, args->vm_id);
 	if (XE_IOCTL_DBG(xe, !vm))
 		return -EINVAL;

 	if (!madvise_args_are_sane(vm->xe, args)) {
 		err = -EINVAL;
 		goto put_vm;
 	}

 	xe_svm_flush(vm);

 	err = down_write_killable(&vm->lock);
 	if (err)
 		goto put_vm;

 	if (XE_IOCTL_DBG(xe, xe_vm_is_closed_or_banned(vm))) {
 		err = -ENOENT;
 		goto unlock_vm;
 	}

 	err = xe_madvise_details_init(vm, args, &details);
 	if (err)
 		goto unlock_vm;

 	err = xe_vm_alloc_madvise_vma(vm, args->start, args->range);
 	if (err)
 		goto madv_fini;

 	err = get_vmas(vm, &madvise_range);
 	if (err || !madvise_range.num_vmas)
 		goto madv_fini;

 	if (madvise_range.has_bo_vmas) {
 		if (args->type == DRM_XE_MEM_RANGE_ATTR_ATOMIC) {
 			if (!check_bo_args_are_sane(vm, madvise_range.vmas,
 						    madvise_range.num_vmas,
 						    args->atomic.val)) {
 				err = -EINVAL;
-				goto madv_fini;
+				goto free_vmas;
 			}
 		}

 		drm_exec_init(&exec, DRM_EXEC_IGNORE_DUPLICATES | DRM_EXEC_INTERRUPTIBLE_WAIT, 0);
 		drm_exec_until_all_locked(&exec) {
 			for (int i = 0; i < madvise_range.num_vmas; i++) {
 				struct xe_bo *bo = xe_vma_bo(madvise_range.vmas[i]);

 				if (!bo)
 					continue;
 				err = drm_exec_lock_obj(&exec, &bo->ttm.base);
 				drm_exec_retry_on_contention(&exec);
 				if (err)
 					goto err_fini;
 			}
 		}
 	}

 	if (madvise_range.has_svm_userptr_vmas) {
 		err = xe_svm_notifier_lock_interruptible(vm);
 		if (err)
 			goto err_fini;
 	}

 	attr_type = array_index_nospec(args->type, ARRAY_SIZE(madvise_funcs));
 	madvise_funcs[attr_type](xe, vm, madvise_range.vmas, madvise_range.num_vmas, args,
 				 &details);

 	err = xe_vm_invalidate_madvise_range(vm, args->start, args->start + args->range);

 	if (madvise_range.has_svm_userptr_vmas)
 		xe_svm_notifier_unlock(vm);

 err_fini:
 	if (madvise_range.has_bo_vmas)
 		drm_exec_fini(&exec);
+free_vmas:
 	kfree(madvise_range.vmas);
 	madvise_range.vmas = NULL;
 madv_fini:
 	xe_madvise_details_fini(&details);
 unlock_vm:
 	up_write(&vm->lock);
 put_vm:
 	xe_vm_put(vm);
 	return err;
 }
